from pathlib import Path
from PIL import Image
import json,html,sys
base=Path(__file__).resolve().parent.parent
journey=base/'QA'/sys.argv[1]/sys.argv[2]/'Journey';out=base/'Captures';out.mkdir(exist_ok=True)
items=[]
for key,label,prefix,baseline in [('LineFormation','Directional item','SequenceR19','LineFormation'),('BombFormation','Bomb','SequenceR19','BombFormation'),('Color','Color item','CreationR21','Color'),('Spark','Firebird item','CreationR21','Spark'),('Multiple','Two items from one swap','CreationR21','Multiple')]:
 samples=[(int(l.split('\t')[0]),float(l.split('\t')[1])) for l in (journey/(prefix+'_'+key+'_Frames.tsv')).read_text().splitlines()]
 paths=[journey/('Mechanics_'+prefix+'_'+key+'_Before.png')]+[journey/('Mechanics_'+prefix+'_'+key+'_'+str(i).zfill(2)+'.png') for i,t in samples]+[journey/('Mechanics_'+prefix+'_'+key+'_After.png')]
 durations=[350]+[max(1,round((samples[i+1][1]-t)*1000)) if i+1<len(samples) else 160 for i,(j,t) in enumerate(samples)]+[1000]
 images=[Image.open(p).convert('RGB') for p in paths]
 for suffix,speed in [('',1),('_Slow',2)]:images[0].save(out/(key+suffix+'.webp'),save_all=True,append_images=images[1:],duration=[d*speed for d in durations],loop=0,lossless=True,method=4)
 for im in images:im.close()
 items.append(dict(key=key,label=label,frames=[str(p.relative_to(base)) for p in paths],animation='Captures/'+key+'.webp',slow='Captures/'+key+'_Slow.webp',baseline='../R21/Captures/'+baseline+'.webp' if baseline else None))
(base/'QA/ReviewCaptures.json').write_text(json.dumps(items,indent=2))
options=''.join('<option value="'+str(i)+'">'+html.escape(x['label'])+'</option>' for i,x in enumerate(items))
page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>R22 — Distinct item formation</title><style>*{box-sizing:border-box}body{margin:0;background:#0b1520;color:#efdfc2;font:17px/1.5 system-ui}main{max-width:1020px;margin:auto;padding:24px}h1,h2{color:#dfb563;line-height:1.2}.layout{display:grid;grid-template-columns:minmax(280px,410px) 1fr;gap:22px;align-items:start}section{background:#142331;border:1px solid #685735;border-radius:10px;padding:18px;margin:16px 0}img{width:100%;height:auto;display:block}button,select{font:inherit;background:#243c4f;color:#f2e6ce;border:1px solid #987b48;padding:9px;margin:4px 0;border-radius:4px;max-width:100%}button{cursor:pointer}select,input{width:100%}label,small{display:block}small{color:#bdc9d2}a{color:#a8d8fa}#status{min-height:3em}@media(max-width:700px){main{padding:14px}.layout{grid-template-columns:1fr}.portrait{max-width:410px;margin:auto}}</style><main><p>Gameplay R22 · Actual Unity review</p><h1>Gather → transform → flourish → settle</h1><p>Each item now has its own formation: directional end-pieces converge, bombs compress and charge, prisms turn into place, and Firebird wings unfold. Independent textured ribbons and plumes sweep around the approved artwork, then fade before the idle handoff.</p><div class="layout"><section class="portrait"><label for="sequence">Creation sequence</label><select id="sequence">OPTIONS</select><button id="play">Play</button> <button id="slow">Half speed</button> <button id="stop">Inspect frame</button> <button id="baseline">Previous R21</button><label for="frame">Captured frame</label><input id="frame" type="range" min="0" value="0"><p id="status"></p><a id="full" target="_blank" rel="noopener">Open full-size capture</a><img id="screen" alt="Actual Unity item creation"><small>576×1280 sampled Unity frames with review holds. Half-speed playback doubles sample intervals. No generated or interpolated frames; silent footage, not a device frame-rate measurement.</small></section><div><section><h2>New choreography</h2><ul><li>Sapphire directional ends snap onto a growing core; the motion rotates with the clear direction.</li><li>Bombs compress, charge and expand with independent amber ignition plumes.</li><li>Color items form through a turning prism, surrounded by opposing textured energy arcs.</li><li>Firebird wings unfold continuously as flame feathers sweep outward.</li><li>Two independent texture layers move behind each item; the body stays legible.</li><li>0.52s completion includes a seamless full-sprite hold. Same-wave creations finish together.</li></ul></section><section><h2>Scope and evidence</h2><p>Applies to match-created R4 directional, bomb, color and Firebird items in the mechanics sandbox. Activation and rainbow conversion effects remain the earlier implementation. Existing rules, moves and campaign Legacy are preserved.</p><p><a href="ImplementationReport.md">Implementation report</a> · <a href="QA/Verification.json">Test results</a> · <a href="QA/Scope.json">File scope</a></p><p>Approved item bodies remain unchanged. New transparent artwork was generated with built-in imagegen and layered in Unity. <a href="AssetReview.html">Inspect the accents on three backgrounds</a>. Activation effects still use R19; this pass targets creation, not the full R20 activation pipeline.</p></section><section><h2>Try it in Unity</h2><p>Home → Development → Gameplay Mechanics Sandbox → R4. The first playtest round creates a directional item; Fixtures includes line-four and square creation.</p><p>Synthetic test boards can display49/4 moves in the playtest HUD. That is a fixture-caption mismatch; move limits were not redesigned.</p><p>Physical-phone performance and user visual acceptance remain outstanding.</p></section></div></div></main><script>const items=ITEMS;const select=document.querySelector('#sequence'),slider=document.querySelector('#frame'),pic=document.querySelector('#screen'),status=document.querySelector('#status');function show(src,label){pic.src=src;document.querySelector('#full').href=pic.src;status.textContent=label;}function still(){const i=items[+select.value];show(i.frames[+slider.value],i.label+' · frame '+(+slider.value+1)+' / '+i.frames.length)}function change(){slider.max=items[+select.value].frames.length-1;slider.value=0;document.querySelector('#baseline').disabled=!items[+select.value].baseline;still()}select.onchange=change;slider.oninput=still;document.querySelector('#play').onclick=()=>show(items[+select.value].animation,items[+select.value].label+' · R22 sampled Unity playback');document.querySelector('#slow').onclick=()=>show(items[+select.value].slow,items[+select.value].label+' · half speed');document.querySelector('#stop').onclick=still;document.querySelector('#baseline').onclick=()=>{const i=items[+select.value];if(i.baseline)show(i.baseline,i.label+' · historical R21 recording')};change();</script></html>'''
(base/'Gameplay_CreationChoreography_R22_Review.html').write_text(page.replace('OPTIONS',options).replace('ITEMS',json.dumps(items)))
print('Built five sequences at normal and half speed; '+str(sum(len(i['frames']) for i in items))+' portraits')
